                                                                                                                                                                                                                       
  CREATE TABLE "CODE_SYSTEM_OPERATION"                                                                                                                                                                      
   (	"SYSTEM_OPERATION_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"SYSTEM_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                             
	"OPERATION_NAME" NVARCHAR2(64),                                                                                                                                                                                       
	"DESCRIPTION" NVARCHAR2(255),                                                                                                                                                                                         
	"ENTRY_URL" NVARCHAR2(255),                                                                                                                                                                                           
	"AUTH_RANGE" NVARCHAR2(512),                                                                                                                                                                                          
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                   
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                            
	"CREATION_DATE" DATE,                                                                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                            
	"UPDATED_DATE" DATE,                                                                                                                                                                                                  
	"IS_ENABLE" NUMBER(1,0),                                                                                                                                                                                              
	"DEL_FLAG" NUMBER(1,0),                                                                                                                                                                                               
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                                         
	 PRIMARY KEY ("SYSTEM_OPERATION_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                                 

